import 'dart:convert';
import 'dart:io';

import 'package:capitalix_owner_customers_example/capitalix_owner_customers.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:test/test.dart';

import 'support/recording_client.dart';

/// Unit tests against responses synthesized from the PINNED contract
/// (test/fixtures/, regenerated by tool/fixtures.sh). Every exchange is
/// recorded to build/traffic-mock.json for `capitalix_contract.py validate`.
String fixture(String name) => File('test/fixtures/$name.json').readAsStringSync();

http.Response json(String name, int status) => http.Response.bytes(
    utf8.encode(fixture(name)), status, headers: {'content-type': 'application/json'});

void main() {
  late RecordingClient recorder;
  late CapitalixApiClient client;
  final responses = <String, http.Response Function()>{};

  setUpAll(() {
    recorder = RecordingClient(MockClient((request) async {
      final key = '${request.method} ${request.url.path}';
      final respond = responses[key];
      if (respond == null) return http.Response('{"message":"no mock for $key"}', 599);
      return respond();
    }));
  });

  setUp(() {
    responses.clear();
    client = CapitalixApiClient(baseUrl: Uri.parse('https://api.example.test'), httpClient: recorder, token: 't');
  });

  tearDownAll(() => recorder.writeTo('build/traffic-mock.json'));

  test('lists customer balances with contract filters and pagination', () async {
    responses['GET ${Endpoints.customerBalances}'] = () => json('customer-balances.200', 200);
    final rows = await CustomersApi(client).listBalances(
        name: 'افق', paymentStatus: PaymentStatus.unpaid, hasDebt: true, page: 2, perPage: 20);
    expect(rows.items, hasLength(1));
    expect(rows.items.single.invoiceCount, 1);
    expect(rows.items.single.paymentStatus, PaymentStatus.partiallyPaid);
    expect(rows.items.single.paidAmount, isA<String>(), reason: 'money stays a decimal string');
    expect(rows.meta.currentPage, 1);
    expect(rows.meta.hasMore, isTrue, reason: 'fixture meta: page 1 of 4');
    final sent = recorder.exchanges.last;
    expect(sent['query'], {'name': 'افق', 'payment_status': 'UNPAID', 'has_debt': 'true', 'page': '2', 'per_page': '20'});
  });

  test('omits null filters (owner-app convention)', () async {
    responses['GET ${Endpoints.customerBalances}'] = () => json('customer-balances.200', 200);
    await CustomersApi(client).listBalances();
    expect(recorder.exchanges.last['query'], isEmpty);
  });

  test('rejects per_page outside the contract range before sending', () {
    expect(() => CustomersApi(client).listBalances(perPage: 101), throwsArgumentError);
  });

  test('creates a customer with the contract field names and parses 201', () async {
    responses['POST ${Endpoints.customers}'] = () => json('customers.store.201', 201);
    final customer = await CustomersApi(client).create(const CustomerInput(
        name: 'شركة الأفق', type: CustomerType.organization, mobile: '0551234567',
        taxNumber: '310122334400003', commercialRegistrationNo: '1010223344'));
    expect(customer.id, isNotEmpty);
    final body = recorder.exchanges.last['body'] as Map;
    expect(body['type'], 'ORGANIZATION');
    expect(body.keys, containsAll(['name', 'type', 'mobile', 'tax_number', 'commercial_registration_no']));
    expect(body.keys, isNot(contains('vat_number')), reason: 'owner-app spec name, not in the contract');
  });

  test('updates with PUT (the contract method), not POST', () async {
    responses['PUT ${Endpoints.customer('c-1')}'] = () => json('customers.update.200', 200);
    await CustomersApi(client).update('c-1', const CustomerInput(name: 'x', type: CustomerType.individual));
    expect(recorder.exchanges.last['method'], 'PUT');
  });

  test('deletes a customer', () async {
    responses['DELETE ${Endpoints.customer('c-1')}'] = () => json('customers.destroy.200', 200);
    await CustomersApi(client).delete('c-1');
    expect(recorder.exchanges.last['status'], 200);
  });

  test('maps 422 to a validation error the app can show', () async {
    responses['POST ${Endpoints.customers}'] = () => json('customers.store.422', 422);
    final error = await CustomersApi(client)
        .create(const CustomerInput(name: '', type: CustomerType.individual))
        .then<ApiException?>((_) => null, onError: (Object e) => e as ApiException);
    expect(error!.isValidation, isTrue);
    expect(error.code, 'VALIDATION_FAILED');
    expect(error.correlationId, isNotNull);
  });

  test('maps 409 to a conflict (send confirm_distinct to proceed)', () async {
    responses['POST ${Endpoints.customers}'] = () => json('customers.store.409', 409);
    expect(
        CustomersApi(client).create(const CustomerInput(name: 'dup', type: CustomerType.individual)),
        throwsA(isA<ApiException>().having((e) => e.isConflict, 'isConflict', isTrue)));
  });

  test('maps 401 to unauthenticated', () async {
    responses['GET ${Endpoints.customerBalances}'] = () => json('customer-balances.401', 401);
    expect(CustomersApi(client).listBalances(),
        throwsA(isA<ApiException>().having((e) => e.isUnauthenticated, 'isUnauthenticated', isTrue)));
  });

  test('maps an undocumented non-JSON 5xx to a generic failure (not recorded)', () async {
    final offContract = CapitalixApiClient(
        baseUrl: Uri.parse('https://api.example.test'),
        httpClient: MockClient((_) async => http.Response('<html>oops</html>', 502)));
    expect(CustomersApi(offContract).listBalances(),
        throwsA(isA<ApiException>().having((e) => e.status, 'status', 502)));
  });

  test('login stores the token from the 201 data', () async {
    responses['POST ${Endpoints.login}'] = () => json('auth.login.201', 201);
    final anonymous = CapitalixApiClient(baseUrl: Uri.parse('https://api.example.test'), httpClient: recorder);
    final token = await AuthApi(anonymous).login(login: 'owner@x.test', password: 'p', deviceName: 'test');
    expect(token, isNotEmpty);
    expect(anonymous.token, token);
  });
}
